import{_ as a,o as t,c as s,a2 as n}from"./chunks/framework.DiXyETtc.js";const u=JSON.parse('{"title":"Remote Agents","description":"","frontmatter":{},"headers":[],"relativePath":"guide/remote-agents.md","filePath":"guide/remote-agents.md","lastUpdated":1795687103000}'),o={name:"guide/remote-agents.md"};function r(l,e,p,d,c,i){return t(),s("div",null,[...e[0]||(e[0]=[n(`<h1 id="remote-agents" tabindex="-1">Remote Agents <a class="header-anchor" href="#remote-agents" aria-label="Permalink to &quot;Remote Agents&quot;">​</a></h1><p>An agent can run in another chamvi app, its <strong>peer</strong>. The calling app declares it with <code>defineRemoteAgent()</code>, and its runs dispatch to it like to any local agent. The peer runs the agent with its own model, tools, sandbox and approvals. A personal assistant app hands coding tasks to a developer app, which owns the repositories and the sandbox. The developer app can call back to the assistant app the same way.</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki chamvi vp-code" tabindex="0"><code><span class="line"><span style="color:#E3E5EA;">npm </span><span style="color:#E7C58C;">install</span><span style="color:#E7C58C;"> @chamvi/peer</span></span></code></pre></div><p><code>@chamvi/peer</code> has the transport and <code>peerModule()</code>. <code>defineRemoteAgent()</code> comes from <code>@chamvi/core</code> (re-exported by <code>@chamvi/app</code>).</p><h2 id="two-apps" tabindex="-1">Two apps <a class="header-anchor" href="#two-apps" aria-label="Permalink to &quot;Two apps&quot;">​</a></h2><p>The calling app, <code>assistants</code>, declares <code>developer</code> as a remote agent at the peer <code>dev</code>:</p><div class="language-ts"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki chamvi vp-code" tabindex="0"><code><span class="line"><span style="color:#80858F;">// the app &quot;assistants&quot;: alfred hands coding work to developer, which the app &quot;dev&quot; runs</span></span>
<span class="line"><span style="color:#8EA7FF;">const</span><span style="color:#E3E5EA;"> developer = defineRemoteAgent({</span></span>
<span class="line"><span style="color:#E3E5EA;">    name: </span><span style="color:#E7C58C;">&#39;developer&#39;</span><span style="color:#E3E5EA;">,</span></span>
<span class="line"><span style="color:#80858F;">    // the peer, and the agent and role there (default: the same name, role &quot;default&quot;)</span></span>
<span class="line"><span style="color:#E3E5EA;">    peer: </span><span style="color:#E7C58C;">&#39;dev&#39;</span><span style="color:#E3E5EA;">,</span></span>
<span class="line"><span style="color:#E3E5EA;">    agent: </span><span style="color:#E7C58C;">&#39;developer&#39;</span><span style="color:#E3E5EA;">,</span></span>
<span class="line"><span style="color:#80858F;">    // who may dispatch to the stand-in here, as for any local agent</span></span>
<span class="line"><span style="color:#E3E5EA;">    channels: [agent.on({ from: [</span><span style="color:#E7C58C;">&#39;alfred&#39;</span><span style="color:#E3E5EA;">] })],</span></span>
<span class="line"><span style="color:#80858F;">    // approvals of the remote run are announced here, never to a caller&#39;s source</span></span>
<span class="line"><span style="color:#E3E5EA;">    approvals: { channel: </span><span style="color:#E7C58C;">&#39;openclaw&#39;</span><span style="color:#E3E5EA;">, address: </span><span style="color:#E7C58C;">&#39;owner&#39;</span><span style="color:#E3E5EA;"> },</span></span>
<span class="line"><span style="color:#80858F;">    // the whole remote run, approvals included (default 24 h)</span></span>
<span class="line"><span style="color:#E3E5EA;">    timeoutMs: </span><span style="color:#E7C58C;">6</span><span style="color:#E3E5EA;"> * </span><span style="color:#E7C58C;">60</span><span style="color:#E3E5EA;"> * </span><span style="color:#E7C58C;">60</span><span style="color:#E3E5EA;"> * </span><span style="color:#E7C58C;">1000</span><span style="color:#E3E5EA;">,</span></span>
<span class="line"><span style="color:#E3E5EA;">});</span></span>
<span class="line"></span>
<span class="line"><span style="color:#8EA7FF;">const</span><span style="color:#E3E5EA;"> alfred = defineModelAgent({</span></span>
<span class="line"><span style="color:#E3E5EA;">    name: </span><span style="color:#E7C58C;">&#39;alfred&#39;</span><span style="color:#E3E5EA;">,</span></span>
<span class="line"><span style="color:#E3E5EA;">    instructions: </span><span style="color:#E7C58C;">&#39;Hand every coding task to the developer and report its outcome.&#39;</span><span style="color:#E3E5EA;">,</span></span>
<span class="line"><span style="color:#E3E5EA;">    tools: dispatchTools({ agents: [{ agent: </span><span style="color:#E7C58C;">&#39;developer&#39;</span><span style="color:#E3E5EA;">, roles: [</span><span style="color:#E7C58C;">&#39;default&#39;</span><span style="color:#E3E5EA;">] }], wait: </span><span style="color:#8EA7FF;">true</span><span style="color:#E3E5EA;"> }),</span></span>
<span class="line"><span style="color:#E3E5EA;">});</span></span>
<span class="line"></span>
<span class="line"><span style="color:#8EA7FF;">export</span><span style="color:#8EA7FF;"> const</span><span style="color:#E3E5EA;"> assistants = createApp({</span></span>
<span class="line"><span style="color:#E3E5EA;">    model: </span><span style="color:#E7C58C;">&#39;anthropic/claude-sonnet-5-5&#39;</span><span style="color:#E3E5EA;">,</span></span>
<span class="line"><span style="color:#E3E5EA;">    agents: [alfred, developer],</span></span>
<span class="line"><span style="color:#E3E5EA;">    modules: [</span></span>
<span class="line"><span style="color:#E3E5EA;">        openclawModule(),</span></span>
<span class="line"><span style="color:#E3E5EA;">        peerModule({</span></span>
<span class="line"><span style="color:#E3E5EA;">            peers: {</span></span>
<span class="line"><span style="color:#E3E5EA;">                dev: {</span></span>
<span class="line"><span style="color:#80858F;">                    // the peer&#39;s public URL: origin plus basePath</span></span>
<span class="line"><span style="color:#E3E5EA;">                    url: </span><span style="color:#E7C58C;">&#39;https://dev.example&#39;</span><span style="color:#E3E5EA;">,</span></span>
<span class="line"><span style="color:#80858F;">                    // the bearer this app sends to dev: a static token of dev&#39;s TOKENS</span></span>
<span class="line"><span style="color:#E3E5EA;">                    outgoing: { token: requireEnv(</span><span style="color:#E7C58C;">&#39;PEER_DEV_TOKEN&#39;</span><span style="color:#E3E5EA;">) },</span></span>
<span class="line"><span style="color:#80858F;">                    // dev calls back (wake, its own remote agents) as the static token &quot;peer-dev&quot; here</span></span>
<span class="line"><span style="color:#E3E5EA;">                    incoming: { token: </span><span style="color:#E7C58C;">&#39;peer-dev&#39;</span><span style="color:#E3E5EA;"> },</span></span>
<span class="line"><span style="color:#E3E5EA;">                },</span></span>
<span class="line"><span style="color:#E3E5EA;">            },</span></span>
<span class="line"><span style="color:#E3E5EA;">        }),</span></span>
<span class="line"><span style="color:#E3E5EA;">    ],</span></span>
<span class="line"><span style="color:#E3E5EA;">});</span></span></code></pre></div><p>The receiving app, <code>dev</code>, runs <code>developer</code>. It accepts the call through an <code>agent.on()</code> role whose <code>from</code> names the peer and the calling agent:</p><div class="language-ts"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki chamvi vp-code" tabindex="0"><code><span class="line"><span style="color:#80858F;">// the app &quot;dev&quot;: developer accepts runs from alfred of the peer &quot;assistants&quot; only</span></span>
<span class="line"><span style="color:#8EA7FF;">const</span><span style="color:#E3E5EA;"> developerAtDev = defineModelAgent({</span></span>
<span class="line"><span style="color:#E3E5EA;">    name: </span><span style="color:#E7C58C;">&#39;developer&#39;</span><span style="color:#E3E5EA;">,</span></span>
<span class="line"><span style="color:#E3E5EA;">    instructions: </span><span style="color:#E7C58C;">&#39;Implement the task in a workspace and open a pull request.&#39;</span><span style="color:#E3E5EA;">,</span></span>
<span class="line"><span style="color:#E3E5EA;">    channels: [agent.on({ from: [</span><span style="color:#E7C58C;">&#39;assistants/alfred&#39;</span><span style="color:#E3E5EA;">] })],</span></span>
<span class="line"><span style="color:#E3E5EA;">});</span></span>
<span class="line"></span>
<span class="line"><span style="color:#8EA7FF;">export</span><span style="color:#8EA7FF;"> const</span><span style="color:#E3E5EA;"> dev = createApp({</span></span>
<span class="line"><span style="color:#E3E5EA;">    model: </span><span style="color:#E7C58C;">&#39;anthropic/claude-sonnet-5-5&#39;</span><span style="color:#E3E5EA;">,</span></span>
<span class="line"><span style="color:#E3E5EA;">    agents: [developerAtDev],</span></span>
<span class="line"><span style="color:#E3E5EA;">    modules: [</span></span>
<span class="line"><span style="color:#E3E5EA;">        peerModule({</span></span>
<span class="line"><span style="color:#E3E5EA;">            peers: {</span></span>
<span class="line"><span style="color:#E3E5EA;">                assistants: {</span></span>
<span class="line"><span style="color:#E3E5EA;">                    url: </span><span style="color:#E7C58C;">&#39;https://assistants.example&#39;</span><span style="color:#E3E5EA;">,</span></span>
<span class="line"><span style="color:#80858F;">                    // assistants calls here as the static token &quot;peer-assistants&quot; (narrow grants)</span></span>
<span class="line"><span style="color:#E3E5EA;">                    incoming: { token: </span><span style="color:#E7C58C;">&#39;peer-assistants&#39;</span><span style="color:#E3E5EA;"> },</span></span>
<span class="line"><span style="color:#80858F;">                    // dev wakes the stand-in when a run settles or waits on an approval</span></span>
<span class="line"><span style="color:#E3E5EA;">                    outgoing: { token: requireEnv(</span><span style="color:#E7C58C;">&#39;PEER_ASSISTANTS_TOKEN&#39;</span><span style="color:#E3E5EA;">) },</span></span>
<span class="line"><span style="color:#80858F;">                    // where dev announces approvals of runs assistants started (optional)</span></span>
<span class="line"><span style="color:#E3E5EA;">                    approvals: { channel: </span><span style="color:#E7C58C;">&#39;openclaw&#39;</span><span style="color:#E3E5EA;">, address: </span><span style="color:#E7C58C;">&#39;owner&#39;</span><span style="color:#E3E5EA;"> },</span></span>
<span class="line"><span style="color:#E3E5EA;">                },</span></span>
<span class="line"><span style="color:#E3E5EA;">            },</span></span>
<span class="line"><span style="color:#E3E5EA;">        }),</span></span>
<span class="line"><span style="color:#E3E5EA;">        openclawModule(),</span></span>
<span class="line"><span style="color:#E3E5EA;">    ],</span></span>
<span class="line"><span style="color:#E3E5EA;">});</span></span></code></pre></div><ul><li>A run of <code>developer</code> in <code>assistants</code> is a <strong>stand-in</strong>. It calls no model and runs no tools. It starts the remote run, waits for it, and settles with the remote run&#39;s outcome. <code>alfred</code> dispatches to it and waits for it as for a local agent (<a href="/guide/dispatch">Dispatch</a>), and the stand-in shows in the dashboard, the REST API and MCP like any run.</li><li>The receiver decides who may call. A <code>from</code> entry <code>&lt;peer&gt;/&lt;agent&gt;</code> matches only a run of <code>&lt;agent&gt;</code> in that peer. The peer name comes from the credential the request carries, never from the request body. A local name in <code>from</code> never matches a peer. All other role rules apply unchanged: <code>schema</code>, <code>maxPerRun</code>, <code>maxDepth</code>, keys.</li><li>Both directions use the same configuration. Each app lists the other under <code>peers</code>, with <code>outgoing</code> to call it and <code>incoming</code> to recognize its calls. A one-way peer leaves one of them out, but the receiver needs <code>outgoing</code> to wake the caller (see <a href="#deadlines">Deadlines</a>).</li></ul><p><code>defineRemoteAgent()</code> takes:</p><table tabindex="0"><thead><tr><th>Option</th><th>Meaning</th></tr></thead><tbody><tr><td><code>name</code></td><td>The agent&#39;s name here</td></tr><tr><td><code>peer</code></td><td>A peer configured in <code>peerModule({ peers })</code>. An unknown peer stops the app at start (<code>InvalidAgentDefinitionError</code>), and <code>chamvi start --check</code> reports it too</td></tr><tr><td><code>agent</code></td><td>The agent at the peer, default <code>name</code></td></tr><tr><td><code>role</code></td><td>Its <code>agent.on()</code> role at the peer, default <code>default</code></td></tr><tr><td><code>channels</code></td><td>The subscriptions here, usually <code>agent.on({ from })</code> for the local callers</td></tr><tr><td><code>output</code></td><td>A Standard Schema the remote output is validated against here. A mismatch fails the stand-in with <code>ValidationError</code></td></tr><tr><td><code>timeoutMs</code></td><td>The deadline of the whole remote run, see <a href="#deadlines">Deadlines</a></td></tr><tr><td><code>approvals</code></td><td><code>{ channel, address }</code>: where approvals of the remote run are announced, see <a href="#approvals">Approvals</a></td></tr><tr><td><code>description</code>, <code>private</code>, <code>concurrencyMaxRuns</code></td><td>As for any agent</td></tr></tbody></table><p>A remote agent has no <code>model</code>, <code>instructions</code>, <code>tools</code>, <code>hooks</code>, <code>state</code> or <code>budget</code>. Those belong to the peer&#39;s agent.</p><h2 id="peers" tabindex="-1">Peers <a class="header-anchor" href="#peers" aria-label="Permalink to &quot;Peers&quot;">​</a></h2><p><code>peerModule({ peers })</code> goes into the app&#39;s <code>modules</code>. Each peer has a name, which follows the agent-name rule:</p><table tabindex="0"><thead><tr><th>Option</th><th>Default</th><th>Meaning</th></tr></thead><tbody><tr><td><code>url</code></td><td>required</td><td>The peer&#39;s public URL, its origin plus its <code>basePath</code> (http or https)</td></tr><tr><td><code>outgoing</code></td><td>none</td><td>How this app authenticates at the peer: <code>{ token }</code> or <code>{ authup: { url, clientId, clientSecret } }</code></td></tr><tr><td><code>incoming</code></td><td>none</td><td>How the peer authenticates here: <code>{ token: &#39;&lt;static token id&gt;&#39; }</code> or <code>{ authupClient: &#39;&lt;client id&gt;&#39; }</code></td></tr><tr><td><code>pollMs</code></td><td><code>60000</code></td><td>How often a remote run is read, at least <code>1000</code></td></tr><tr><td><code>untrusted</code></td><td><code>false</code></td><td>Every result from this peer taints the run that receives it, and every run this peer starts here is tainted from the start</td></tr><tr><td><code>approvals</code></td><td>none</td><td><code>{ channel, address }</code>: where this app announces approvals of runs the peer started</td></tr></tbody></table><p><code>approvalUrl</code> is this app&#39;s approval link, which the peer shows to its users. It defaults to the dashboard link built from <code>PUBLIC_URL</code>, and stays unset without one. A misconfigured peer throws <code>InvalidAgentDefinitionError</code> when <code>peerModule()</code> is called.</p><h2 id="credentials" tabindex="-1">Credentials <a class="header-anchor" href="#credentials" aria-label="Permalink to &quot;Credentials&quot;">​</a></h2><p>A peer authenticates like any other client. No principal kind is specific to peers.</p><ul><li><strong>Static token.</strong> At the receiver, the peer is an ordinary <code>TOKENS</code> entry. <code>incoming: { token: &#39;&lt;id&gt;&#39; }</code> names that entry&#39;s <code>id</code>. The caller sends the entry&#39;s secret as <code>outgoing: { token }</code>.</li><li><strong>authup.</strong> The caller fetches a token with client credentials (<code>outgoing: { authup: { url, clientId, clientSecret } }</code>). The token is cached until shortly before it expires and fetched again once after a 401. The receiver recognizes the client with <code>incoming: { authupClient: &#39;&lt;client id&gt;&#39; }</code>. Only a client signed in through the receiver&#39;s <code>authup()</code> authenticator matches.</li></ul><p>A run started by a peer acts with the grants of the peer&#39;s credential. The calling app&#39;s name is shown on the run for display only. The start needs <code>chamvi_agent_run</code> for the agent. An agent the peer may not start answers 404, like a missing agent, so the peer cannot find out which agents exist. Reading, cancelling and waking a run the peer started needs no further grant. On every other route the peer&#39;s credential is an ordinary principal: <code>chamvi_agent_run</code> for an agent also reads that agent&#39;s non-private runs. <strong>Give a peer token the narrowest grants it needs</strong>, usually <code>chamvi_agent_run</code> for the agents it calls:</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki chamvi vp-code" tabindex="0"><code><span class="line"><span style="color:#8EA7FF;">export</span><span style="color:#E3E5EA;"> TOKENS=</span><span style="color:#E7C58C;">&#39;[</span></span>
<span class="line"><span style="color:#E7C58C;">  { &quot;value&quot;: &quot;&lt;admin secret&gt;&quot;, &quot;id&quot;: &quot;admin&quot;, &quot;permissions&quot;: &quot;*&quot; },</span></span>
<span class="line"><span style="color:#E7C58C;">  { &quot;value&quot;: &quot;&lt;peer secret&gt;&quot;, &quot;id&quot;: &quot;peer-assistants&quot;, &quot;permissions&quot;: [</span></span>
<span class="line"><span style="color:#E7C58C;">    { &quot;permission&quot;: { &quot;name&quot;: &quot;chamvi_agent_run&quot; }, &quot;policies&quot;: [{ &quot;type&quot;: &quot;attributes&quot;, &quot;query&quot;: { &quot;name&quot;: &quot;developer&quot; } }] }</span></span>
<span class="line"><span style="color:#E7C58C;">  ] }</span></span>
<span class="line"><span style="color:#E7C58C;">]&#39;</span></span></code></pre></div><p>The transport sends a request only to the peer&#39;s own origin and never follows a redirect, so the bearer reaches no other host. No secret appears in an error message or a log.</p><h2 id="how-a-call-runs" tabindex="-1">How a call runs <a class="header-anchor" href="#how-a-call-runs" aria-label="Permalink to &quot;How a call runs&quot;">​</a></h2><ol><li>The stand-in sends one start. The start is an effect keyed by the stand-in&#39;s run id, so a start whose answer was lost is sent again and reaches the same remote run. Once the remote run id is recorded, no start is sent again, also after a restart on another replica.</li><li>The stand-in waits (<code>waiting</code>, kind <code>remote</code>). Every <code>pollMs</code>, one replica reads the remote run (<code>GET /runs/:id</code>, the peer&#39;s view of the runs it started). When the remote run settles or waits on an approval, the peer sends a wake (<code>POST /runs/:id/wake</code>, no content). The wake makes the next poll happen at once. Every peer gets 202 for a wake, also for a stand-in that settled meanwhile; only a request from a credential that is no peer gets 404.</li><li>The stand-in settles with the remote outcome. A completed run gives its output, validated by <code>output</code> when given. A failed run gives its error (<code>remote_failed</code> when the peer reports none). A cancelled run cancels the stand-in.</li></ol><p>Cancelling the stand-in cancels the remote run, best effort. A start that the peer answers with 400, 401, 403, 404, 415, a 413 without <code>Retry-After</code> (the start, with its attachments, is above the peer&#39;s body limit), a 409 or a redirect has a problem a resend does not fix, so the stand-in fails with <code>ValidationError</code> at once. A start answered with a 429, a 5xx, a network error, a 413 with <code>Retry-After</code> or a 409 for a passing condition (<code>entity_conflict</code>, <code>entity_deadlock</code>, <code>agent_replaced</code>, <code>invalid_run_state</code>) is sent again. A failed read is reported to <code>onError</code> and tried again in the next window, or after the peer&#39;s <code>Retry-After</code> when that is longer. Both stop at the deadline.</p><p>The stand-in adds no dispatch level. The start sends the depth of the calling run, so <code>alfred</code>&#39;s call lands at depth 1 in <code>dev</code>, as a local dispatch would. The default <code>maxDepth</code> of 1 allows it.</p><h2 id="trust" tabindex="-1">Trust <a class="header-anchor" href="#trust" aria-label="Permalink to &quot;Trust&quot;">​</a></h2><p>Taint crosses peers in both directions (<a href="/guide/tools#untrusted-content-and-outbound-tools">Untrusted content</a>):</p><ul><li>A tainted caller starts a tainted remote run (<code>peer:&lt;peer&gt;</code>), and so does any caller from a peer the receiver configured <code>untrusted</code>. The remote agent&#39;s outbound tools are gated from its first step.</li><li>A stand-in is tainted (<code>peer:&lt;peer&gt;/&lt;remoteRunId&gt;</code>) when the remote run was tainted, or when the peer is configured <code>untrusted</code>. The taint is stored before the output reaches the caller, so the waiting parent is tainted before it sees the result.</li></ul><p>A peer&#39;s results and requests are only as trustworthy as the peer. Mark a peer you do not operate yourself <code>untrusted: true</code>.</p><h2 id="approvals" tabindex="-1">Approvals <a class="header-anchor" href="#approvals" aria-label="Permalink to &quot;Approvals&quot;">​</a></h2><p>An approval inside the remote run, or in a run it dispatched, belongs to the app that runs it. <strong>It is answered only there</strong>, in that app&#39;s dashboard or API. The calling app shows it on the stand-in: the title and the peer&#39;s link. It never answers it: the receiver refuses an answer from a peer&#39;s credential with 404, whatever grants that credential holds.</p><ul><li><code>defineRemoteAgent({ approvals: { channel, address } })</code> announces each remote approval once through that channel, with the title and the peer&#39;s link. Without it, nothing is sent, and the approval shows only on the stand-in.</li><li><code>peers.&lt;name&gt;.approvals</code> announces, at the receiver, approvals of runs that peer started.</li></ul><p>Both destinations are fixed in code. A remote approval never goes to the source of an ancestor run, such as the chat the request came from, because a peer could otherwise reach that conversation.</p><h2 id="deadlines" tabindex="-1">Deadlines <a class="header-anchor" href="#deadlines" aria-label="Permalink to &quot;Deadlines&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Deadline</th><th>Value</th></tr></thead><tbody><tr><td>A peer request (start, read, cancel, wake)</td><td>30 s</td></tr><tr><td>The poll of a remote run</td><td>Every <code>pollMs</code> (60 s) across all replicas; at once after a wake</td></tr><tr><td>The whole remote run (<code>timeoutMs</code>)</td><td>24 h by default, at most <code>APPROVAL_TIMEOUT_MAX_MS</code></td></tr></tbody></table><p><code>timeoutMs</code> counts from the stand-in&#39;s creation: a stand-in that has not started its remote run by then fails with <code>Timeout</code>, and its wait expires at that same deadline, however long the start took. When the wait expires, the stand-in fails with <code>Timeout</code> and sends the remote run one cancel, best effort. A stand-in that never started its remote run has no remote run id, so nothing is cancelled there.</p><h2 id="errors" tabindex="-1">Errors <a class="header-anchor" href="#errors" aria-label="Permalink to &quot;Errors&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Code</th><th>Where</th><th>Meaning</th></tr></thead><tbody><tr><td><code>remote_failed</code></td><td>The stand-in&#39;s <code>run.error</code></td><td>The remote run failed without an error of its own</td></tr><tr><td><code>peer_start_busy</code></td><td>503 on <code>POST /agents/:name/runs</code> from a peer, with <code>Retry-After</code></td><td>Another start of the same parent and role holds the count. The caller retries</td></tr><tr><td><code>peer_request</code></td><td><code>onError</code></td><td>A retryable peer request failure (<code>PeerRequestError</code> of <code>@chamvi/peer</code>)</td></tr></tbody></table><h2 id="in-the-dashboard" tabindex="-1">In the dashboard <a class="header-anchor" href="#in-the-dashboard" aria-label="Permalink to &quot;In the dashboard&quot;">​</a></h2><p>A waiting stand-in shows <code>&lt;peer&gt;/&lt;agent&gt;</code>, the remote run id and, while the remote run waits on an approval, its title and a link that opens the peer&#39;s approval page in a new tab. A remote agent&#39;s card reads <code>remote: &lt;peer&gt;/&lt;agent&gt;</code>. Stand-ins never fill the approvals inbox: the approval is answered at the peer.</p>`,42)])])}const E=a(o,[["render",r]]);export{u as __pageData,E as default};
